<?php require __DIR__.'/includes/bootstrap.php';$slug=trim($_GET['slug']??'');if(!$pdo||$slug===''){http_response_code(404);exit('Product not found');}$s=$pdo->prepare("SELECT id,affiliate_url FROM products WHERE slug=? AND status='published' LIMIT 1");$s->execute([$slug]);$product=$s->fetch();if(!$product||!filter_var($product['affiliate_url'],FILTER_VALIDATE_URL)){http_response_code(404);exit('Product not found');}$host=parse_url($product['affiliate_url'],PHP_URL_HOST);if(!$host||!preg_match('/(^|\.)[a-z0-9-]+\.[a-z]{2,}$/i',$host)){http_response_code(404);exit('Product not found');}$ip=$_SERVER['REMOTE_ADDR']??'';$q=$pdo->prepare('INSERT INTO affiliate_clicks(product_id,referrer,ip_hash,user_agent) VALUES(?,?,?,?)');$q->execute([$product['id'],substr($_SERVER['HTTP_REFERER']??'',0,500),$ip?hash('sha256',$ip):null,substr($_SERVER['HTTP_USER_AGENT']??'',0,500)]);header('Location: '.$product['affiliate_url'],true,302);exit;
